/**
 * Vercel Serverless Function: /api/chat
 *
 * POST { sessionId, message, userLang, page }      visitor message (stored; AI reply if configured)
 * POST { sessionId, action: 'bot', text }          log a reply generated by the in-browser bot
 * POST { sessionId, lead: {...}, message }         legacy lead capture
 * GET  ?sessionId=…&since=<ts>                      poll for agent messages (real-time human takeover)
 */
import { sendInquiryEmails } from '../scripts/emailService.js';
import { rateLimit, clientIp } from '../lib/db.js';
import { ensureChat, getChat, addChatMessage, chatMessages, createLead, updateChat } from '../lib/store.js';

const SESSION_RE = /^sess_[A-Za-z0-9-]{16,64}$/;

const SYSTEM_PROMPT = `You are the official AI Solutions Strategist for Zavron Solutions (https://www.zavronsolutions.com), an elite US digital solutions agency founded by Muhammad Junaid.
We specialize in:
- Custom Web Engineering (Next.js, React, Node.js, TypeScript)
- Enterprise WordPress & Headless CMS
- High-Converting E-Commerce (Shopify Plus & WooCommerce)
- Technical SEO, Core Web Vitals, Google Maps 3-Pack, Topical Authority
- Google Ads PPC & Social Media Marketing
- UI/UX & Conversion Rate Optimization (CRO)

CRITICAL INSTRUCTIONS:
1. Detect and reply in the EXACT language of the user:
   - If the user speaks Roman Urdu / Hindi (e.g. "mujhy kuch or poochana hai as a humanbaat karo", "rates kya hain", "website banwani hai"), reply fluently in natural, warm Roman Urdu!
   - If the user speaks Urdu (Urdu script), reply in respectful, professional Urdu.
   - If Spanish, reply in Spanish. If Arabic, in Arabic. If French, in French. If German, in German. If English, in English.
2. Tone: Friendly, highly competent, professional, consultative, and human-like.
3. If the user asks to speak to a human or Muhammad Junaid:
   Warmly explain that they can connect directly with Muhammad Junaid or our US senior technical leadership for a free 15-minute discovery consultation, and invite them to leave their contact details.
4. If the user wants a website audit, tell them to share their website URL (e.g. company.com) so you can run an instant live audit. NEVER suggest auditing zavronsolutions.com.
5. Keep answers concise, clear, and well-structured.`;

function body(req) {
  if (!req.body) return {};
  if (typeof req.body === 'string') { try { return JSON.parse(req.body); } catch { return {}; } }
  return req.body;
}

async function aiReply(message, history) {
  if (!process.env.OPENAI_API_KEY || !message) return null;
  try {
    const r = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${process.env.OPENAI_API_KEY}` },
      body: JSON.stringify({
        model: 'gpt-4o-mini',
        temperature: 0.6,
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          ...history.slice(-10).filter((m) => m.from === 'user' || m.from === 'bot' || m.from === 'admin')
            .map((m) => ({ role: m.from === 'user' ? 'user' : 'assistant', content: m.text })),
        ],
      }),
    });
    if (!r.ok) return null;
    const j = await r.json();
    return j.choices?.[0]?.message?.content || null;
  } catch (e) {
    console.error('OpenAI error in api/chat.js:', e.message);
    return null;
  }
}

export default async function handler(req, res) {
  res.setHeader('Cache-Control', 'no-store');
  if (req.method === 'OPTIONS') return res.status(200).end();

  try {
    /* ------------------------------------------------ visitor polling */
    if (req.method === 'GET') {
      const sid = String(req.query.sessionId || '');
      if (!SESSION_RE.test(sid)) return res.status(400).json({ success: false, error: 'Invalid session' });
      const chat = await getChat(sid);
      if (!chat) return res.status(200).json({ success: true, adminJoined: false, closed: false, messages: [] });
      const since = Number(req.query.since) || 0;
      const msgs = (await chatMessages(sid, since)).filter((m) => m.from === 'admin' || m.from === 'system');
      return res.status(200).json({
        success: true,
        adminJoined: Boolean(chat.adminJoined),
        closed: Boolean(chat.closed),
        agentName: chat.agentName || 'Muhammad Junaid',
        serverTime: Date.now(),
        messages: msgs.map((m) => ({ id: m.id, from: m.from, text: m.text, ts: m.ts })),
      });
    }

    if (req.method !== 'POST') return res.status(405).json({ success: false, error: 'Method Not Allowed' });

    const data = body(req);
    const sid = String(data.sessionId || '');
    if (!SESSION_RE.test(sid)) return res.status(400).json({ success: false, error: 'Invalid session' });
    if (!(await rateLimit(`chat:${clientIp(req)}`, 120, 600))) {
      return res.status(429).json({ success: false, error: 'Too many messages. Please slow down.' });
    }

    /* ---------------------------------------- bot reply logging */
    if (data.action === 'bot') {
      const chat = await getChat(sid);
      if (chat && !chat.adminJoined && data.text) await addChatMessage(sid, 'bot', String(data.text).slice(0, 4000));
      return res.status(200).json({ success: true });
    }

    /* ---------------------------------------- legacy lead capture */
    if (data.lead && data.lead.email) {
      const lead = data.lead;
      await ensureChat(sid, { page: data.page });
      await updateChat(sid, { userInfo: { name: lead.name || '', email: lead.email, phone: lead.phone || '' } });
      await createLead({ name: lead.name, email: lead.email, phone: lead.phone, service: lead.service || 'Live Chatbot Inquiry', message: lead.details || data.message || 'Live chat session', source: 'Live Chatbot', sessionId: sid });
      try {
        await sendInquiryEmails({ name: lead.name || 'Chatbot Prospect', email: lead.email, phone: lead.phone || 'N/A', service: lead.service || 'Live Chatbot Inquiry', message: lead.details || data.message || 'Live chat session', source: 'Live Chatbot' });
      } catch (err) { console.error('Chat lead email error:', err.message); }
      return res.status(200).json({ success: true, sessionId: sid });
    }

    /* ---------------------------------------- visitor message */
    const message = String(data.message || '').trim().slice(0, 4000);
    if (!message) return res.status(400).json({ success: false, error: 'Empty message' });
    const { chat } = await addChatMessage(sid, 'user', message, { page: data.page, lang: data.userLang });

    // A human agent is handling this conversation: the bot stays silent
    if (chat.adminJoined) {
      return res.status(200).json({ success: true, sessionId: sid, adminJoined: true, reply: null, aiGenerated: false });
    }

    const history = await chatMessages(sid);
    const reply = await aiReply(message, history);
    if (reply) await addChatMessage(sid, 'bot', reply);

    return res.status(200).json({ success: true, sessionId: sid, adminJoined: false, reply, aiGenerated: Boolean(reply) });
  } catch (error) {
    console.error('api/chat error:', error);
    return res.status(500).json({ success: false, error: 'Chat service error' });
  }
}
